Check ($cs.Count -eq 324) 'candidate schema must contain 324 rows';Check ($cfld.Count -eq 120) 'candidate fields must contain 120 rows';Check ($creq.Count -eq 792) 'candidate requirements must contain 792 rows'
foreach($n in @('candidate-schema-columns.csv','candidate-fields.csv','candidate-field-requirements.csv')){$q=Profile (Join-Path $cand $n);Check ($q.valid -and -not $q.bom -and $q.bare_lf -eq 0 -and $q.bare_cr -eq 0 -and $q.crlf -gt 0 -and $q.final) "candidate CSV encoding/newline wrong: $n"}
$nr=@($cs|Where-Object schema_column_id -eq 'SCOL-FIELDS-CSV-013');Check ($nr.Count -eq 1) 'new schema row missing';if($nr.Count -eq 1){$nr=$nr[0];Check ($nr.table_path -ceq '数据/fields.csv' -and $nr.column_name -ceq 'allowed_requirement_target_kinds' -and $nr.ordinal -ceq '13' -and $nr.data_type -ceq 'text') 'new schema row identity/type wrong';Check ($nr.is_nullable -ceq 'false' -and $nr.is_primary_key -ceq 'false' -and $nr.semicolon_forbidden -ceq 'false' -and $nr.review_status -ceq 'approved') 'new schema row constraints/status wrong'}
$schemaCols=@(($schema|Select-Object -First 1).PSObject.Properties.Name);for($i=0;$i -lt $schema.Count;$i++){Check ($cs[$i].schema_column_id -ceq $schema[$i].schema_column_id) "schema row order drift at $i";foreach($c0 in $schemaCols){Check ([string]$cs[$i].$c0 -ceq [string]$schema[$i].$c0) "unauthorized schema cell drift: $($schema[$i].schema_column_id).$c0"}}
$cfBy=@{};foreach($x in $cfld){$cfBy[$x.field_id]=$x};$baseFieldCols=@(($fields|Select-Object -First 1).PSObject.Properties.Name);foreach($f in $fields){Check ($cfBy.ContainsKey($f.field_id)) "candidate field missing: $($f.field_id)";if(-not $cfBy.ContainsKey($f.field_id)){continue};$x=$cfBy[$f.field_id];foreach($c0 in $baseFieldCols){if($c0 -eq 'allowed_subject_kinds'){Check ([string]$x.$c0 -ceq $factAllow[$f.field_id]) "candidate fact contract mismatch: $($f.field_id)"}else{Check ([string]$x.$c0 -ceq [string]$f.$c0) "unauthorized candidate field drift: $($f.field_id).$c0"}};Check ([string]$x.allowed_requirement_target_kinds -ceq $reqAllow[$f.field_id]) "candidate requirement contract mismatch: $($f.field_id)"}
$crBy=@{};foreach($x in $creq){$crBy[$x.requirement_id]=$x};$reqCols=@(($req|Select-Object -First 1).PSObject.Properties.Name);foreach($r in $req){Check ($crBy.ContainsKey($r.requirement_id)) "candidate requirement missing: $($r.requirement_id)";if(-not $crBy.ContainsKey($r.requirement_id)){continue};$x=$crBy[$r.requirement_id];foreach($c0 in $reqCols){$expected=[string]$r.$c0;if($ovBy.ContainsKey($r.requirement_id)){$o=$ovBy[$r.requirement_id];if($c0 -eq $Col[$o.current_target_kind]){$expected=''};if($c0 -eq $Col[$o.proposed_target_kind]){$expected=$o.proposed_target_id};if($c0 -eq 'requirement_fingerprint'){$expected=$o.proposed_requirement_fingerprint}};Check ([string]$x.$c0 -ceq $expected) "unauthorized candidate requirement drift: $($r.requirement_id).$c0"}}
$mm=@(Import-Csv -LiteralPath (Join-Path $cand 'formal-migration-manifest.csv'));Check ($mm.Count -eq 166) 'formal migration manifest must contain 166 cell/file entries';Check (@($mm|Where-Object target_path -eq '数据/fields.csv').Count -eq 122) 'field manifest delta must be 122';Check (@($mm|Where-Object target_path -eq '数据/schema-columns.csv').Count -eq 11) 'schema manifest must describe one 11-cell inserted row';Check (@($mm|Where-Object target_path -eq '数据/field-requirements.csv').Count -eq 32) 'requirement manifest delta must be 32';Check (@($mm|Where-Object target_path -eq 'scripts/validation/Validate-ResearchData.ps1').Count -eq 1) 'validator manifest must be one exact file replacement'
$vs=Get-Content -LiteralPath (Join-Path $cand 'verification-summary.json') -Raw -Encoding UTF8|ConvertFrom-Json;Check ($vs.verdict -ceq 'accept' -and [int]$vs.formal_baseline_validator_checks -eq 93378) 'candidate verification summary lacks 93,378-check accept';Check ([int]$vs.negative_tests -eq 6 -and [int]$vs.negative_tests_passed -eq 6) 'candidate negative tests are incomplete';Check ($vs.candidate_csv_utf8_no_bom -eq $true -and $vs.candidate_csv_crlf_only -eq $true -and $vs.candidate_csv_final_crlf -eq $true) 'candidate CSV format summary wrong'
$vp=Join-Path $cand 'Validate-ResearchData.ps1'
if(Test-Path -LiteralPath $vp){$tok=$null;$pe=$null;[void][Management.Automation.Language.Parser]::ParseFile($vp,[ref]$tok,[ref]$pe);Check ($pe.Count -eq 0) "candidate validator parse errors: $($pe-join'; ')";$vt=Get-Content -LiteralPath $vp -Raw -Encoding UTF8;foreach($pattern in @("ValidateSet\('audit','gate'\)","SubjectContractMode\s*=\s*'gate'",'allowed_subject_kinds','allowed_requirement_target_kinds','value_available','conflicting_unresolved','FIELD-ID-ARCH','implements_architecture','same-target same-field fact')){Check ($vt -match $pattern) "validator missing contract token: $pattern"};Check ( -not ($vt -match '(?im)^\s*(Set-Content|Add-Content|Out-File|Export-Csv|Copy-Item|Move-Item|Remove-Item|New-Item)\b|\[System\.IO\.File\]::Write')) 'candidate validator contains filesystem write';$vprof=Profile $vp;Check ($vprof.valid -and $vprof.bom) 'candidate validator must be valid UTF-8 with BOM';Check ($vprof.bare_cr -eq 0 -and $vprof.bare_lf -gt 0) 'candidate validator must use LF as primary newline and no bare CR';Check ( -not $vprof.final) 'candidate validator must have no final newline';Write-Output "CANDIDATE-VALIDATOR-BYTES: sha256=$(Hash $vp); bytes=$($vprof.bytes); crlf=$($vprof.crlf); bare_lf=$($vprof.bare_lf); final_newline=$($vprof.final)"}
$fr=Join-Path $cand 'formal-validator-readonly-run.txt';if(Test-Path -LiteralPath $fr){$t=Get-Content -LiteralPath $fr -Raw -Encoding UTF8;Check ($t -match 'PASS: 32-table research data model; 93378 checks executed\.') 'candidate formal run not refreshed to 93,378';Check ($t -match 'Registry: 323 columns, 488 enum values\.') 'candidate formal run registry wrong'}
if(Blank $IndependentReviewPath){Warn 'technical preflight does not include an independent exact-accept signoff'}else{$rp=Full $root $IndependentReviewPath;Check (Test-Path -LiteralPath $rp -PathType Leaf) "review missing: $rp";if(Test-Path -LiteralPath $rp){$rt=Get-Content -LiteralPath $rp -Raw -Encoding UTF8;Check ($rt -match '(?m)^裁决[：:]\s*`?accept`?\s*$') 'independent review is not exact accept'}}
foreach($e in $manifest){$p=Full $root $e.path;if(Test-Path -LiteralPath $p){Check ((Hash $p) -ceq $start[$e.path]) "formal input changed during preflight: $($e.path)"}}
foreach($n in $candStart.Keys){$p=Join-Path $cand $n;Check (Test-Path -LiteralPath $p) "candidate disappeared: $n";if(Test-Path -LiteralPath $p){Check ((Hash $p) -ceq $candStart[$n]) "candidate changed during preflight: $n"}}
foreach($m in $script:Warnings){Write-Output "WARNING: $m"}
if($script:Errors.Count){Write-Output "FAIL: $($script:Errors.Count) preflight error(s); $($script:Checks) checks executed.";foreach($m in $script:Errors){Write-Output " - $m"};exit 1}
Write-Output "PASS: field-contract migration technical preflight; $($script:Checks) checks executed."
Write-Output 'Expected delta: schema +1 row; fields +1 column/120 values and 2 fact-contract cells; requirements 12 rows/32 cells; validator exact-byte replacement; facts/enums unchanged.'
Write-Output 'This read-only result does not authorize migration without independent exact accept and byte-for-byte backup.'
exit 0